    $conn = new PDO("mysql:host=$servername;dbname=$dbname", $username, $password);\n    // 设置 PDO 错误模式为异常\n    $conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
