package ormimport (
	"database/sql"
	"errors"
	"fmt"
	"reflect"
	"strings"
)type ORM struct {
	db *sql.DB
}func NewORM(db *sql.DB) *ORM {
	return &ORM{db: db}
}func (o *ORM) Insert(table string, data interface{}) (int64, error) {
	value := reflect.ValueOf(data)
	if value.Kind() != reflect.Struct {
		return 0, errors.New("data is not a struct")
	}	fields := make([]string, 0)
	values := make([]interface{}, 0)	for i := 0; i < value.NumField(); i++ {
		field := value.Type().Field(i)
		if field.Tag.Get("orm") == "" {
			continue
		}
		fields = append(fields, field.Tag.Get("orm"))
		values = append(values, value.Field(i).Interface())
	}	query := fmt.Sprintf("INSERT INTO %s (%s) VALUES (%s)",
		table,
		strings.Join(fields, ", "),
		strings.TrimRight(strings.Repeat("?, ", len(values)), ", "),
	)	result, err := o.db.Exec(query, values...)
	if err != nil {
		return 0, err
	}	return result.LastInsertId()
}func (o *ORM) Select(table string, where string, args ...interface{}) ([]map[string]interface{}, error) {
	query := fmt.Sprintf("SELECT * FROM %s", table)
	if where != "" {
		query = fmt.Sprintf("%s WHERE %s", query, where)
	}	rows, err := o.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()	columns, err := rows.Columns()
	if err != nil {
		return nil, err
	}	result := make([]map[string]interface{}, 0)	for rows.Next() {
		values := make([]interface{}, len(columns))
		valuePtrs := make([]interface{}, len(columns))		for i := range columns {
			valuePtrs[i] = &values[i]
		}		err := rows.Scan(valuePtrs...)
		if err != nil {
			return nil, err
		}		rowData := make(map[string]interface{})
		for i, column := range columns {
			rowData[column] = values[i]
		}		result = append(result, rowData)
	}	return result, nil
}```使用示例：```
